import os
import re
import glob
from pathlib import Path

import pandas as pd
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D  # noqa: F401 – needed for 3-D projection side-effect

# ----------------------------------------------------------------------------
# Configuration
# ----------------------------------------------------------------------------
# Directory that contains the snapshot text files generated by deal.II
SNAPSHOT_DIR = Path(
    "/home/oth/BSC/benchmark/observatory_benchmark/ResultAnalysis/"
    "diffusion_ground_truth/dealii/examples/step-26_1/build/"
    "diffusion_data_snapshots"
)

# Regular expression to parse a single line of the form
#   "Subbox (x, y, z): value"
LINE_RE = re.compile(r"Subbox \((\d+), (\d+), (\d+)\):\s*([0-9eE+\-.]+)")

# ----------------------------------------------------------------------------
# Helpers
# ----------------------------------------------------------------------------

def parse_snapshot_file(path: Path, snap_idx: int) -> pd.DataFrame:
    """Parse a single snapshot text file into a DataFrame.

    The resulting DataFrame has columns: snap, x, y, z, conc.
    """
    records = []
    with path.open() as fh:
        for line in fh:
            m = LINE_RE.match(line.strip())
            if not m:
                # Ignore lines that do not conform to the expected pattern
                continue
            x, y, z, val = m.groups()
            records.append(
                {
                    "snap": snap_idx,
                    "x": int(x),
                    "y": int(y),
                    "z": int(z),
                    "conc": float(val),
                }
            )
    return pd.DataFrame(records)


# ----------------------------------------------------------------------------
# Main processing
# ----------------------------------------------------------------------------

def main():
    if not SNAPSHOT_DIR.exists():
        raise FileNotFoundError(
            f"Snapshot directory not found: {SNAPSHOT_DIR}. Update SNAPSHOT_DIR"
        )

    # Snapshot filenames are of the form "average_concentration_<idx>.txt" –
    # we want to sort them numerically, not lexicographically.

    def _extract_idx(path: Path) -> int:
        m = re.search(r"(\d+)", path.stem)
        return int(m.group(1)) if m else -1

    snapshot_files = sorted(SNAPSHOT_DIR.glob("*.txt"), key=_extract_idx)
    if not snapshot_files:
        raise RuntimeError(f"No .txt snapshot files found in {SNAPSHOT_DIR}")

    # Parse all snapshots into a single DataFrame
    all_frames = []
    for idx, file in enumerate(snapshot_files):
        df = parse_snapshot_file(file, snap_idx=idx)
        all_frames.append(df)

    data = pd.concat(all_frames, ignore_index=True)

    # Compute the average concentration per voxel across *all* snapshots
    voxel_avg = (
        data.groupby(["x", "y", "z"], as_index=False)["conc"].mean().rename(
            columns={"conc": "conc_avg"}
        )
    )

    # Compute per-snapshot mean and standard deviation over all voxels
    snap_stats = (
        data.groupby("snap", as_index=False)["conc"].agg(["mean", "std"]).reset_index()
        .rename(columns={"mean": "conc_mean", "std": "conc_std"})
    )

    # Save time-series CSV (mean + std)
    ts_csv = SNAPSHOT_DIR / "average_concentration_time_series.csv"
    snap_stats.to_csv(ts_csv, index=False)
    print(f"[INFO] Saved time-series stats to {ts_csv.relative_to(Path.cwd())}")

    # ----------------------------------------------------------------------------
    # Plotting – dynamics over time only, save high-quality files (no 3-D scatter)
    # ----------------------------------------------------------------------------

    save_dir = Path("./ResultAnalysis/plots/diffusion_ground_truth_plots")
    save_dir.mkdir(parents=True, exist_ok=True)

    # Cohesive aesthetics (match other diffusion plots)
    plt.rcParams.update({
        "font.family": "sans-serif",
        "font.size": 8,
        "axes.labelsize": 9,
        "axes.titlesize": 9,
        "xtick.labelsize": 8,
        "ytick.labelsize": 8,
        "lines.linewidth": 1.8,
        "axes.linewidth": 0.8,
        "xtick.major.width": 0.8,
        "ytick.major.width": 0.8,
        "xtick.major.size": 3,
        "ytick.major.size": 3,
        "figure.dpi": 400,
    })

    plt.figure(figsize=(4, 2.5), dpi=400)

    x = snap_stats["snap"]
    y = snap_stats["conc_mean"]
    yerr = snap_stats["conc_std"]

    plt.plot(
        x,
        y,
        color="#666666",  # gray line for cohesion
        linestyle="-",
        linewidth=1.8,
    )

    # Remove top and right spines to match other diffusion plots
    ax = plt.gca()
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    plt.xlabel("Timestep")
    plt.ylabel("Concentration (μM)")

    for ext, fmt_kwargs in {
        "pdf": {"format": "pdf"},
        "svg": {"format": "svg"},
        "png": {"format": "png", "dpi": 600},
    }.items():
        plt.savefig(save_dir / f"average_concentration_timecourse.{ext}",
                    bbox_inches="tight", pad_inches=0.1, **fmt_kwargs)

    plt.close()


if __name__ == "__main__":
    main()

